mapper.update:
update data_reconcile_run_t
   set status = 'INITIALIZING',
       coordinator_id = #{workerId},
       started_at = coalesce(started_at, #{now}),
       updated_time = #{now}
 where tid = #{runId}
   and tenant_id = #{tenantId}
   and status = 'PENDING'

