mapper.update:
update data_reconcile_bucket_t
   set status = #{status},
       error_message = #{errorMessage},
       worker_id = null,
       finished_at = case
           when #{retry} = 1 then finished_at
           else #{now}
       end,
       updated_time = #{now}
 where tenant_id = #{tenantId}
   and run_id = #{runId}
   and tid = #{bucketId}

