mapper.sql:
merge into data_reconcile_diff_t target using (
select #{row.tid} tid, #{row.tenantId} tenant_id, #{row.runId} run_id, #{row.bucketId} bucket_id, #{row.diffHash} diff_hash, #{row.businessKey} business_key, #{row.diffType} diff_type, #{row.fieldName} field_name, #{row.sourceValueMasked} source_value_masked, #{row.targetValueMasked} target_value_masked, #{row.sourceRowHash} source_row_hash, #{row.targetRowHash} target_row_hash, #{row.createdTime} created_time from dual
) source on ( target.tenant_id = source.tenant_id and target.run_id = source.run_id and target.diff_hash = source.diff_hash ) when not matched then insert ( tid, tenant_id, run_id, bucket_id, diff_hash, business_key, diff_type, field_name, source_value_masked, target_value_masked, source_row_hash, target_row_hash, resolve_status, created_time ) values ( source.tid, source.tenant_id, source.run_id, source.bucket_id, source.diff_hash, source.business_key, source.diff_type, source.field_name, source.source_value_masked, source.target_value_masked, source.source_row_hash, source.target_row_hash, 'OPEN', source.created_time )
